public sealed class FakeCoverageRegister : ICoverageRegister
{
    public FakeCoverageRegister(Coverage? findResult)
    {
        FindResult = findResult;
    }

    public Coverage? FindResult { get; }
    public int FindCalls { get; private set; }
    public string? LastPolicyNumber { get; private set; }

    public Coverage? Find(string policyNumber)
    {
        FindCalls++;
        LastPolicyNumber = policyNumber;
        return FindResult;
    }
}

public sealed class FakeRiskScreen : IRiskScreen
{
    public FakeRiskScreen(int scoreResult)
    {
        ScoreResult = scoreResult;
    }

    public int ScoreResult { get; }
    public int ScoreCalls { get; private set; }
    public Claim? LastClaim { get; private set; }

    public int Score(Claim claim)
    {
        ScoreCalls++;
        LastClaim = claim;
        return ScoreResult;
    }
}

